it('passes the validation rejection result back to the provider on the next round', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'fail', description: 'desc', inputSchema: {type: 'object', required: ['x']}},
    async () => 'ok'
  );

  let capturedMessages: Message[] = [];
  const provider: AIProvider = {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      capturedMessages = [...params.messages];
      if (capturedMessages.length !== 1) {
        yield {type: 'text', text: 'done'};
        yield {type: 'stop', stopReason: 'end_turn'};
        return;
      }

      yield {type: 'tool_use', toolCall: {id: 'c1', name: 'fail', input: {}}};
      yield {type: 'stop', stopReason: 'tool_use'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };

  const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
  await orchestrator.processMessage(createSession('ask'));

  const toolResult = capturedMessages[2] as ToolResultMessage;
  const content = toolResult.content[0];
  expect({
    count: capturedMessages.length,
    role: toolResult.role,
    contentType: content.type,
    contentBody: content.content,
  }).toEqual({
    count: 3, // [user, assistant-tool-use, user-tool-result]
    role: 'user',
    contentType: 'tool_result',
    contentBody: expect.stringMatching(/Validation failed.*missing required property: x/),
  });
});

it('does not leak offending values to logs on validation failure', async () => {
  interface LogEntry {
    category: string;
    message: string;
    fields?: Record<string, unknown>;
  }
  const recordedLogs: LogEntry[] = [];
  const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
    recordedLogs.push({category, message, fields});
  };
  const loggerMock: Logger = {
    debug: recordLine,
    info: recordLine,
    warn: recordLine,
    error: recordLine,
  };
  setLogger(loggerMock);

  try {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'secret-tool',
        description: 'desc',
        inputSchema: {type: 'object', properties: {secret: {type: 'number'}}},
      },
      async () => 'ok'
    );

    await registry.execute('secret-tool', {secret: 'my-password'});

    const logLine = recordedLogs.find(l => l.message === 'validation failed');
    expect({
      logDefined: logLine !== undefined,
      logContent: JSON.stringify(logLine),
    }).toEqual({
      logDefined: true,
      logContent: expect.not.stringContaining('my-password'),
    });
  } finally {
    setLogger(undefined);
  }
});

